/bin/bash -lc "python - <<'PY'
from sim import Sim
import mujoco, numpy as np
sim=Sim()
model=sim.model
# list sites and bodies containing 'hand' or 'grip'
print('Bodies with hand/grip/finger:')
for i in range(model.nbody):
    name=mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_BODY,i)
    if name and any(k in name for k in ['hand','finger','grip','ee','tcp']):
        print(i,name)
print('Sites:')
for i in range(model.nsite):
    name=mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_SITE,i)
    if name:
        if any(k in name for k in ['hand','finger','grip','ee','tcp','attach']):
            print(i,name,sim.data.site_xpos[i])
print('geom names with handle?')
for i in range(model.ngeom):
    name=mujoco.mj_id2name(model,mujoco.mjtObj.mjOBJ_GEOM,i)
    if name and 'drawer_handle' in name:
        print('drawer_handle geom id',i)
PY"

